import { ActionDefinition } from '../../../Action'
import { DocumentIdColumn, ReferenceColumn, TableNameColumn } from '../../../../db'

export const copyAttachment = ActionDefinition({
    $id: '30fe6cdb0f973300dfd3694e68767e5a',
    name: 'Copy Attachment',
    description:
        'Copies an attachment to a target record. The source is an attachment record. You can dynamically add and configure fields for the record. Server-side validation rules are enforced (data policy, business rules, dictionary-defined mandatory fields), but UI policy does not apply.',
    category: 'a20738df9363130079b5925cf67ffb74',
    inputs: {
        target_record: DocumentIdColumn({
            label: 'Target Record',
            mandatory: true,
            default: 'ef43c6d40a0a0b5700c77f9bf387afe3',
            dependent: 'table',
        }),
        attachment_record: ReferenceColumn({
            label: 'Source Attachment Record',
            mandatory: true,
            referenceTable: 'sys_attachment',
        }),
        table: TableNameColumn({
            label: 'Table',
            mandatory: true,
        }),
    },
    outputs: {},
})
